sys_script.script:
(function () {
    var entregaSysId = current.getValue('entrega');
    if (entregaSysId) {
        var gr = new GlideRecord('x_915815_smart_log_entrega');
        if (gr.get(entregaSysId)) {
            gr.setValue('risco_atraso', 'alto');
            var tempoAdicional = parseInt(current.getValue('tempo_adicional_min'), 10);
            if (tempoAdicional > 0) {
                var etaValue = gr.getValue('eta_atualizado');
                if (!etaValue) {
                    etaValue = gr.getValue('previsao_original');
                }
                if (etaValue) {
                    var gdt = new GlideDateTime(etaValue);
                    gdt.addSeconds(tempoAdicional * 60);
                    gr.setValue('eta_atualizado', gdt.getValue());
                }
            }
            gr.update();
        }
    }
})();
